// Embedded consent tool-access island bundle. Generated by
// `pnpm -F dashboard build:consent` from client/dashboard/src/consent-tools;
// never hand-edit the asset. The island's styles are inlined in the JS (the
// consent page already relies on inline styles), so one script is the whole
// deliverable.

package mcp

import (
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"net/http"

	"github.com/go-chi/chi/v5"

	"github.com/speakeasy-api/gram/server/internal/oops"
)

//go:embed consent_assets/consent-tools.js
var consentToolsScriptData []byte

// consentToolsScriptHash is the first 8 hex chars of the SHA-256 of the
// bundle, used to cache-bust the immutable script URL. Matches the
// consent-page script convention.
var consentToolsScriptHash = func() string {
	sum := sha256.Sum256(consentToolsScriptData)
	return hex.EncodeToString(sum[:])[:8]
}()

// consentToolsScriptURL is the path the consent template loads the island
// from. Hardcoded to the /mcp surface so /x/mcp pages reuse the same route.
var consentToolsScriptURL = "/mcp/consent-tools-" + consentToolsScriptHash + ".js"

// ServeConsentToolsScript serves the island bundle with immutable cache
// headers. Mounted at `GET /mcp/consent-tools-{hash}.js`. The hash in the
// path is content-derived, so a mismatch is a stale URL.
func (s *Service) ServeConsentToolsScript(w http.ResponseWriter, r *http.Request) error {
	if chi.URLParam(r, "hash") != consentToolsScriptHash {
		w.WriteHeader(http.StatusNotFound)
		return nil
	}

	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
	w.WriteHeader(http.StatusOK)
	if _, err := w.Write(consentToolsScriptData); err != nil {
		return oops.E(oops.CodeUnexpected, err, "write consent tools script response").LogError(r.Context(), s.logger)
	}
	return nil
}
